import React, { useState, useImperativeHandle, forwardRef, useEffect, useRef } from 'react';
import Carousel from 'react-multi-carousel';
import 'react-multi-carousel/lib/styles.css';
import ReactPlayer from 'react-player/lazy'
import MioPlayerWrapper from '../mio/mioPlayerWrapper.js';

const Slideshow = forwardRef(({ mediaSrcs, projectName, isProjectOpen, onMediaLoaded }, ref) => {
  const [loaded, setLoaded] = useState(new Array(mediaSrcs.length).fill(false));
  const [slideIndex, setSlideIndex] = useState(0);
  const [showStatic, setShowStatic] = useState(false);
  const carousel = useRef();
  const playerRefs = useRef([]);

  useImperativeHandle(ref, () => ({
    resetSlideIndex: () => carousel.current.goToSlide(0, true)
  }));

  useEffect(() => {
    playerRefs.current.forEach((player, index) => {
      if (player) {
        if (index === slideIndex) {
        } else {
          player.seekTo(0);
        }

        if (!isProjectOpen) {
          player.seekTo(0);
        }
      }
    });

    if (!isProjectOpen) {
      setSlideIndex(0);
    }
  }, [slideIndex, isProjectOpen]);

  useEffect(() => {
    if (loaded[0]) {
      onMediaLoaded();
    }
  }, [loaded]);

  const getMediaType = (src) => {
    if (src.includes('youtube.com') || src.includes('youtu.be')) {
      return 'youtube';
    }
    const extension = src.split('.').pop().toLowerCase();
    if (['jpg', 'jpeg', 'png', 'gif'].includes(extension)) {
      return 'image';
    } else if (['mp4', 'webm', 'ogg'].includes(extension)) {
      return 'video';
    } else if (extension === 'mio') { 
      return 'mio';
    }
    return 'unknown';
  };

  const handleLoad = (index) => {
    setLoaded(prevLoaded => {
      const newLoaded = [...prevLoaded];
      newLoaded[index] = true;
      return newLoaded;
    });
  };

  const handleSlideChange = (newIndex) => {
    setShowStatic(true);
    setTimeout(() => {
      setShowStatic(false);
      setSlideIndex(newIndex);
    }, 200);
  };

  const responsive = {
    desktop: {
      breakpoint: { max: 3000, min: 1024 },
      items: 1,
      slidesToSlide: 1 // optional, default to 1.
    },
    tablet: {
      breakpoint: { max: 1024, min: 464 },
      items: 1,
      slidesToSlide: 1 // optional, default to 1.
    },
    mobile: {
      breakpoint: { max: 464, min: 0 },
      items: 1,
      slidesToSlide: 1 // optional, default to 1.
    }
  };

  return (
    <div style={{ position: 'relative'}}>
      {showStatic && (
        <img
          src="static.webp"
          alt="Static"
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            width: '100%',
            height: '100%',
            zIndex: 1000,
          }}
        />
      )}
      <Carousel ref={carousel}
        responsive={responsive}
        arrows={isProjectOpen && mediaSrcs.length > 1 }
        showDots={isProjectOpen && mediaSrcs.length > 1}
        removeArrowOnDeviceType={[]}
        renderDotsOutside={true}
        draggable={false}
        swipeable={false}
        customTransition="all"
        beforeChange={(nextSlide, { currentSlide, onMove }) => handleSlideChange(nextSlide)}
        dotListClass="custom-dot-list-style">
        {mediaSrcs.map((src, index) => {
          const mediaType = getMediaType(src);
          return (
            <div key={index}>
              {mediaType === 'image' ? (
                <img
                  className={`mySlides ${loaded[index] ? 'fade-in' : 'fade-out'}`}
                  src={src}
                  alt={projectName}
                  onLoad={() => handleLoad(index)}
                  style={{ display: loaded[index] ? 'block' : 'none' }}
                />
              ) : (mediaType === 'video' || mediaType === 'youtube') && isProjectOpen ? (
                <ReactPlayer
                  ref={el => playerRefs.current[index] = el}
                  config={{ 
                    youtube: {
                      playerVars: { playsinline: 1 }
                    },
                    file: {
                      attributes: {
                        playsInline: true 
                      }
                    }
                  }}
                  loop={true} 
                  playsinline={true}
                  controls={isProjectOpen} 
                  height='200%' width='100%' 
                  volume={0.2} 
                  url={src} 
                  playing={index === slideIndex && isProjectOpen}
                  onReady={() => handleLoad(index)}
                />
              ): mediaType === 'mio' && isProjectOpen ? (
                <MioPlayerWrapper
                  src={src}
                  onLoaded={() => handleLoad(index)}
                />
            ) : null}
            </div>
          );
        })}
      </Carousel>
    </div>
  );
});

export default Slideshow;
